    const heap = [];                                // 小顶堆，按节点的值比较
    const up = (i) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p].val <= heap[i].val) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const down = (i) => {
        while (true) {
            const l = 2 * i + 1, r = l + 1;
            let s = i;
            if (l < heap.length && heap[l].val < heap[s].val) s = l;
            if (r < heap.length && heap[r].val < heap[s].val) s = r;
            if (s === i) break;
            [heap[s], heap[i]] = [heap[i], heap[s]];
            i = s;
        }
    };
    for (const node of lists) {
        if (node) {
            heap.push(node);
            up(heap.length - 1);
        }
    }
    const dummy = new ListNode();
    let cur = dummy;
    while (heap.length) {
        const node = heap[0], last = heap.pop();    // 弹出堆顶
        if (heap.length) {
            heap[0] = last;
            down(0);
        }
        cur.next = node;
        cur = node;
        if (node.next) {
            heap.push(node.next);
            up(heap.length - 1);
        }
    }
    return dummy.next;
