class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        if (lists.length == 0) {
            return null;
        }
        int n = lists.length;
        while (n > 1) {                                 // 每一轮个数减半
            int m = 0;
            for (int i = 0; i < n; i += 2) {            // 相邻两个合并，结果放回前面
                lists[m++] = merge2(lists[i], i + 1 < n ? lists[i + 1] : null);
            }
            n = m;
        }
        return lists[0];
    }

    private ListNode merge2(ListNode a, ListNode b) {   // 合并两个有序链表
        ListNode dummy = new ListNode(), cur = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) {
                cur.next = a;
                a = a.next;
            } else {
                cur.next = b;
                b = b.next;
            }
            cur = cur.next;
        }
        cur.next = a != null ? a : b;
        return dummy.next;
    }
}

