class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        def walk(node):
            while node:
                yield node
                node = node.next
        dummy = tail = ListNode()
        for node in heapq.merge(*map(walk, lists), key=lambda n: n.val):
            tail.next = tail = node
        tail.next = None
        return dummy.next

